import{_ as n,C as r,c as s,o as i,a3 as t,G as e}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"BoM variants","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/advanced-configuration/bom-variants.md","filePath":"master/supply-chain/manufacturing/advanced-configuration/bom-variants.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/manufacturing/advanced-configuration/bom-variants.md"};function p(c,a,u,h,d,m){const o=r("ImagePopup");return i(),s("div",null,[a[0]||(a[0]=t('<h1 id="bom-variants" tabindex="-1">BoM variants <a class="header-anchor" href="#bom-variants" aria-label="Permalink to &quot;BoM variants&quot;">​</a></h1><p>Some products come in variants, such as different colours or sizes. One BoM can serve all of them. You mark the components and steps that apply only to certain variants. Everything you leave unmarked applies to every variant.</p><blockquote><p><strong>In simple words:</strong> Apply on Variants lets one BoM build several versions of a product.</p></blockquote><p>Open <code>Manufacturing → Products → Bills of Materials</code>.</p><h2 id="product-variant-on-the-bom" tabindex="-1">Product Variant on the BoM <a class="header-anchor" href="#product-variant-on-the-bom" aria-label="Permalink to &quot;Product Variant on the BoM&quot;">​</a></h2><p>On the BoM form, <strong>Product</strong> is the main product. <strong>Product Variant</strong> lists the variants of that product. Pick one when the BoM is meant for a single variant. Choosing a variant also loads the unit of measure and company from it.</p>',6)),e(o,{src:"/images1/manufacturing/var_bom_product_variant.png",alt:"BoM form General box with Product and Product Variant filled for a product that has variants"}),a[1]||(a[1]=t('<h2 id="apply-on-variants" tabindex="-1">Apply on Variants <a class="header-anchor" href="#apply-on-variants" aria-label="Permalink to &quot;Apply on Variants&quot;">​</a></h2><p>The <strong>Apply on Variants</strong> column is optional on the <strong>Components</strong> tab and the <strong>Operations</strong> tab. Show it from the column toggle.</p><ul><li>Choose one or more variant values, such as a colour.</li><li>Leave it empty: the line is used for every variant.</li><li>Fill it: the line is used only when the order is for a variant that has all the chosen values.</li></ul><p>You can also set <strong>Apply on Variants</strong> on the operation form. The list shows only the values of the BoM product. See <a href="./operations.html">Operations</a>.</p>',4)),e(o,{src:"/images1/manufacturing/var_components_apply_on_variants.png",alt:"BoM Components tab with the Apply on Variants column visible and one component restricted to a variant value"}),a[2]||(a[2]=t('<h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A laptop comes in Silver and Black. Both use a <strong>Motherboard</strong>, so leave its <strong>Apply on Variants</strong> empty. Set <strong>Laptop Chassis</strong> to the colour value for each variant. A Black order then picks the black chassis only.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Variant matching needs a product with variant values. <strong>Business Laptop</strong> in the sample data is a single product, so every line applies to it.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../basic-setup/bill-of-materials.html">Bill of materials</a></li><li><a href="./operations.html">Operations</a></li><li><a href="./../basic-setup/configure-product.html">Configure product</a></li></ul>',5))])}const _=n(l,[["render",p]]);export{f as __pageData,_ as default};
